import os
import pandas as pd
import xgboost as xgb
import joblib
import mlflow
from sklearn.model_selection import GridSearchCV
from sklearn.preprocessing import StandardScaler, OneHotEncoder, OrdinalEncoder
from sklearn.compose import ColumnTransformer
from sklearn.pipeline import Pipeline
from sklearn.metrics import classification_report

# Set local MLflow tracking for CI/CD production runs (no ngrok needed in GitHub Actions)
mlflow.set_tracking_uri("http://localhost:5000")
mlflow.set_experiment("Tourism_MLOps_Experiment")

# 1. Load the saved train and test splits generated by prep.py
Xtrain = pd.read_csv("Xtrain.csv")
Xtest = pd.read_csv("Xtest.csv")
ytrain = pd.read_csv("ytrain.csv").squeeze()
ytest = pd.read_csv("ytest.csv").squeeze()

print("Train and test datasets loaded successfully.")

# 2. Define exact feature lists matching your development environment
numeric_features = [
    "Age",
    "DurationOfPitch",
    "NumberOfPersonVisiting",
    "NumberOfFollowups",
    "NumberOfTrips",
    "NumberOfChildrenVisiting",
    "MonthlyIncome",
]

categorical_features = [
    "TypeofContact",
    "Occupation",
    "Gender",
    "MaritalStatus",
]

ordinal_features = [
    "CityTier",
    "PreferredPropertyStar",
    "PitchSatisfactionScore",
    "ProductPitched",
    "Designation",
]

ordinal_categories = [
    [1, 2, 3],                                                    # CityTier
    [3, 4, 5],                                                    # PreferredPropertyStar
    [1, 2, 3, 4, 5],                                              # PitchSatisfactionScore
    ["Basic", "Standard", "Deluxe", "Super Deluxe", "King"],      # ProductPitched
    ["Executive", "Manager", "Senior Manager", "AVP", "VP"],      # Designation
]

binary_features = [
    "Passport",
    "OwnCar",
]

# 3. Handle class imbalance
class_weight = (ytrain == 0).sum() / (ytrain == 1).sum()

# 4. Build ColumnTransformer with distinct encoders per column group
preprocessor = ColumnTransformer(
    transformers=[
        ("numeric", StandardScaler(), numeric_features),
        ("categorical", OneHotEncoder(handle_unknown="ignore"), categorical_features),
        (
            "ordinal",
            OrdinalEncoder(
                categories=ordinal_categories,
                handle_unknown="use_encoded_value",
                unknown_value=-1,
            ),
            ordinal_features,
        ),
        ("binary", "passthrough", binary_features),
    ],
    remainder="drop",
)

# 5. Define base XGBoost classifier
xgb_model = xgb.XGBClassifier(
    scale_pos_weight=class_weight,
    random_state=42,
    eval_metric="logloss",
)

# 6. Single-combination param_grid using the winning parameters from development
param_grid = {
    "xgbclassifier__colsample_bylevel": [0.6],
    "xgbclassifier__colsample_bytree": [0.6],
    "xgbclassifier__learning_rate": [0.1],
    "xgbclassifier__max_depth": [4],
    "xgbclassifier__n_estimators": [100],
    "xgbclassifier__reg_lambda": [0.4],
}

# 7. Create full Pipeline
model_pipeline = Pipeline(
    steps=[
        ("preprocessor", preprocessor),
        ("xgbclassifier", xgb_model),
    ]
)

# 8. Train, evaluate, and log with MLflow
with mlflow.start_run():
    grid_search = GridSearchCV(
        model_pipeline,
        param_grid,
        cv=5,
        n_jobs=-1,
    )
    grid_search.fit(Xtrain, ytrain)

    # Log nested run(s)
    results = grid_search.cv_results_
    for i, params in enumerate(results["params"]):
        with mlflow.start_run(nested=True):
            mlflow.log_params(params)
            mlflow.log_metric("mean_test_score", results["mean_test_score"][i])
            mlflow.log_metric("std_test_score", results["std_test_score"][i])

    # Log best parameters in parent run
    mlflow.log_params(grid_search.best_params_)
    print("Best Parameters:", grid_search.best_params_)

    # Evaluate best model with custom threshold
    best_model = grid_search.best_estimator_
    classification_threshold = 0.45

    y_pred_train_proba = best_model.predict_proba(Xtrain)[:, 1]
    y_pred_train = (y_pred_train_proba >= classification_threshold).astype(int)

    y_pred_test_proba = best_model.predict_proba(Xtest)[:, 1]
    y_pred_test = (y_pred_test_proba >= classification_threshold).astype(int)

    train_report = classification_report(ytrain, y_pred_train, output_dict=True)
    test_report = classification_report(ytest, y_pred_test, output_dict=True)

    mlflow.log_metrics({
        "train_accuracy": train_report["accuracy"],
        "train_precision": train_report["1"]["precision"],
        "train_recall": train_report["1"]["recall"],
        "train_f1-score": train_report["1"]["f1-score"],
        "test_accuracy": test_report["accuracy"],
        "test_precision": test_report["1"]["precision"],
        "test_recall": test_report["1"]["recall"],
        "test_f1-score": test_report["1"]["f1-score"],
    })

    print("\nTraining Classification Report:")
    print(classification_report(ytrain, y_pred_train))

    print("\nTesting Classification Report:")
    print(classification_report(ytest, y_pred_test))

    # 9. Save the final trained model to tourism_project/deployment/
    os.makedirs("tourism_project/deployment", exist_ok=True)
    model_path = "tourism_project/deployment/best_tourism_model_v1.joblib"
    joblib.dump(best_model, model_path)
    mlflow.log_artifact(model_path, artifact_path="model")
    print(f"Best model saved successfully at: {model_path}")
